mapper.select:
SELECT mh.id AS mastery_id, mh.knowledge_node_id AS node_id,
       mh.old_score, mh.new_score, mh.change_reason, mh.created_at
FROM mastery_history mh
WHERE mh.course_id = #{courseId} AND mh.student_id = #{studentId}

    AND mh.knowledge_node_id = #{nodeId}

ORDER BY mh.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM mastery_history mh
WHERE mh.course_id = #{courseId} AND mh.student_id = #{studentId}

    AND mh.knowledge_node_id = #{nodeId}
